@staticmethod
def _is_ephemeral_verification_path(path: str) -> bool:
    """Erkennt nur typische ad-hoc Testartefakte; getrackte Dateien werden nie dadurch ignoriert."""
    rel = str(path or "").strip().replace("\\", "/")
    name = Path(rel).name.lower()
    if not name.endswith((".php", ".py", ".js", ".ts", ".sh")):
        return False
    return bool(
        re.search(
            r"(?:^test[_-]|[_-](?:test|tests|spec|check|verification)\.(?:php|py|js|ts|sh)$|"
            r"^(?:check|verify|verification)[_-]|^comprehensive[_-]test\.)",
            name,
            re.I,
        )
    )

def _tracked_in_head(self, rel: str) -> bool:
    proc = subprocess.run(
        ["git", "ls-files", "--error-unmatch", "--", rel],
        cwd=self.state.workspace,
        text=True,
        capture_output=True,
        timeout=10,
    )
    return proc.returncode == 0

def _mark_external_mutation(self, before: dict[str, str], after: dict[str, str], source: str) -> None:
    changed = {path for path, fingerprint in after.items() if before.get(path) != fingerprint}
    removed_dirty = set(before) - set(after)

    # Ein ad-hoc Testskript wird oft im Workspace erzeugt, erfolgreich ausgeführt
    # und danach wieder gelöscht. Das Löschen ist dann keine neue Produktmutation:
    # der finale Produktcode ist unverändert gegenüber dem soeben verifizierten Stand.
    ephemeral_cleanup = {
        path for path in removed_dirty
        if self._is_ephemeral_verification_path(path) and not self._tracked_in_head(path)
    }
    if ephemeral_cleanup:
        removed_dirty -= ephemeral_cleanup
        self.state.files_changed.difference_update(ephemeral_cleanup)
        self.logger.emit(
            "test",
            "Temporäre ungetrackte Verifikationsdatei(en) bereinigt; Produkt-Verifikationsstand bleibt gültig.",
            paths=sorted(ephemeral_cleanup),
            epoch=self.state.mutation_epoch,
        )

    if not changed and not removed_dirty:
        return
    self.state.mutation_epoch += 1
    for path in sorted(changed):
        if path and not path.startswith(("__pycache__/", ".pytest_cache/", ".mypy_cache/", ".ruff_cache/", ".venv/", "node_modules/")):
            self.state.files_changed.add(path)
    self.logger.emit(
        "write",
        f"Workspace wurde durch {source} verändert.",
        mutation_epoch=self.state.mutation_epoch,
        files=sorted(self.state.files_changed),
        shell_changed=sorted(changed),
        shell_removed=sorted(removed_dirty),
    )

@staticmethod
def _verification_script_has_failure_contract(content: str, suffix: str) -> bool:
    text = str(content or "")
    if suffix.lower() == ".php":
        return bool(
            re.search(r"\bassert\s*\(", text, re.I)
            or re.search(r"\bthrow\s+new\b", text, re.I)
            or re.search(r"\b(?:exit|die)\s*\(\s*[1-9]\d*\s*\)", text, re.I)
        )
    if suffix.lower() == ".py":
        return bool(
            re.search(r"(?m)^\s*assert\s+", text)
            or re.search(r"\braise\s+AssertionError\b", text)
            or re.search(r"\bsys\.exit\s*\(\s*[1-9]\d*\s*\)", text)
            or re.search(r"\b(?:unittest|pytest)\b", text)
        )
    return False

def _scripted_behavior_test_paths(self, command: str) -> list[str]:
    """Extrahiert direkte PHP/Python-Testskripte aus einfachen Shell-Segmenten."""
    paths: list[str] = []
    for segment in re.split(r"\s*(?:&&|\|\||;)\s*", str(command or "")):
        try:
            tokens = shlex.split(segment)
        except ValueError:
            continue
        if len(tokens) < 2:
            continue
        interpreter = Path(tokens[0]).name.lower()
        if interpreter not in ("php", "python", "python3"):
            continue
        script = ""
        for token in tokens[1:]:
            if token.startswith("-"):
                continue
            suffix = Path(token).suffix.lower()
            if (interpreter == "php" and suffix == ".php") or (
                interpreter in ("python", "python3") and suffix == ".py"
            ):
                script = token
                break
        if script and self._is_ephemeral_verification_path(script):
            paths.append(script)
    return paths

def _is_test_command(self, command: str) -> bool:
    if any(p.search(command) for p in TEST_PATTERNS):
        return True
    for rel in self._scripted_behavior_test_paths(command):
        try:
            candidate = self._resolve(rel, must_exist=True)
            content = candidate.read_text(encoding="utf-8", errors="ignore")
        except (AgentError, OSError):
            continue
        if self._verification_script_has_failure_contract(content, candidate.suffix):
            return True
    return False
